script='''
// Demo fleet: positions are animated along illustrative routes, never a live agency feed.
var fleet=[{id:'FLT-042',crew:'Babatunde A.',zone:'IKJ-04',place:'Ikeja Central',speed:24,load:62,stops:'8/12',state:'On route',pos:.19,period:92},{id:'FLT-018',crew:'Musa K.',zone:'IKJ-05',place:'Ojodu',speed:18,load:44,stops:'7/12',state:'On route',pos:.68,period:125},{id:'FLT-063',crew:'Adaeze N.',zone:'IKJ-06',place:'Agege South',speed:0,load:81,stops:'10/12',state:'Collecting',pos:.37,period:0}], selectedTruck=0, running=true, zoomLevel=1, elapsed=0,lastFrame=0,drawerMode='stop';
var fleetNodes=fleet.map(function(t,i){return document.getElementById('truck'+i)}),fleetPaths=fleet.map(function(t,i){return document.getElementById('fleetPath'+i)}),lengths=fleetPaths.map(function(p){return p.getTotalLength()});
function selectTruck(i){selectedTruck=i;var t=fleet[i];fleetNodes.forEach(function(g,n){g.classList.toggle('selected',n===i)});document.getElementById('vName').textContent='LAWMA · '+t.id;document.getElementById('vCrew').textContent=t.crew+' · '+t.place;document.getElementById('vState').textContent=t.state.toUpperCase();document.getElementById('vSpeed').textContent=t.speed;document.getElementById('vLoad').textContent=t.load+'%';document.getElementById('vStops').textContent=t.stops;document.getElementById('vehiclePreview').hidden=false;}
fleetNodes.forEach(function(g,i){g.addEventListener('click',function(){selectTruck(i)});g.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectTruck(i);showVehicle()}})});
function drawFleet(ms){if(!lastFrame)lastFrame=ms;var dt=Math.min((ms-lastFrame)/1000,.1);lastFrame=ms;if(running)elapsed+=dt;fleet.forEach(function(t,i){var f=(t.pos+(t.period?elapsed/t.period:0))%1,pt=fleetPaths[i].getPointAtLength(f*lengths[i]);fleetNodes[i].setAttribute('transform','translate('+pt.x+' '+pt.y+')');});var sec=12*3600+8*60+41+Math.floor(elapsed);document.getElementById('feedClock').textContent=(running?'DEMO LIVE · ':'PAUSED · ')+[Math.floor(sec/3600)%24,Math.floor(sec/60)%60,sec%60].map(function(n){return String(n).padStart(2,'0')}).join(':');requestAnimationFrame(drawFleet)}
document.getElementById('liveToggle').onclick=function(){running=!running;this.textContent=running?'Ⅱ':'▶';this.setAttribute('aria-label',running?'Pause simulated vehicle movement':'Resume simulated vehicle movement');this.setAttribute('aria-pressed',String(!running));};
function applyZoom(){document.getElementById('geoScene').style.transform='scale('+zoomLevel+')'}document.getElementById('zoomIn').onclick=function(){zoomLevel=Math.min(2.2,zoomLevel+.2);applyZoom()};document.getElementById('zoomOut').onclick=function(){zoomLevel=Math.max(.8,zoomLevel-.2);applyZoom()};document.getElementById('fitMap').onclick=function(){zoomLevel=1;applyZoom()};document.getElementById('mapLayers').onclick=function(){var off=document.getElementById('geoScene').classList.toggle('hide-stops');this.setAttribute('aria-pressed',String(off));this.title=off?'Show property events':'Hide property events'};document.getElementById('mapMore').onclick=function(){document.getElementById('vehiclePreview').hidden=!document.getElementById('vehiclePreview').hidden};
var baseDrawer=document.querySelector('.drawer').innerHTML;
function bindClose(){document.getElementById('drawerClose').onclick=closeDrawer}
var originalOpenDrawer=openDrawer;openDrawer=function(el){if(drawerMode==='vehicle'){document.querySelector('.drawer').innerHTML=baseDrawer;bindClose();drawerMode='stop';document.getElementById('drawerEvidence').onclick=function(){say('Illustrative evidence metadata — no field photo supplied')};document.getElementById('drawerHistory').onclick=function(){say('Event recorded at '+current.dataset.time)}}originalOpenDrawer(el)};
function showVehicle(){var t=fleet[selectedTruck];drawerMode='vehicle';document.querySelector('.drawer').innerHTML='<div class="drawer-top"><div><div class="eyebrow">LAWMA FLEET · DEMONSTRATION</div><h3>'+t.id+'</h3></div><button class="drawer-close" id="drawerClose" aria-label="Close vehicle details">×</button></div><div class="truck-hero"><svg viewBox="0 0 96 55"><use href="#wasteTruck" width="96" height="55"/></svg></div><div class="fleet-status-line"><span>'+t.state+' · '+t.speed+' km/h</span><span>GPS reporting</span></div><div class="drawer-stat"><div><small>Assigned crew</small><b>'+t.crew+'</b></div><div><small>Operating zone</small><b>'+t.zone+' · '+t.place+'</b></div><div><small>Verified stops</small><b>'+t.stops+'</b></div><div><small>Estimated load</small><b>'+t.load+'%</b></div><div><small>Vehicle class</small><b>Waste compactor</b></div><div><small>Connectivity</small><b>4G · Connected</b></div></div><div class="drawer-actions"><button id="showTruckRoute">Show assigned route</button><button class="secondary" id="pauseTruckFeed">'+(running?'Pause movement':'Resume movement')+'</button></div><p class="simulation-note">Demonstration vehicle, crew and telemetry. Movement follows illustrative routes; no live LAWMA fleet connection is active.</p>';bindClose();document.getElementById('showTruckRoute').onclick=function(){closeDrawer();zoomLevel=1;applyZoom();document.getElementById('mapHeading').textContent=t.id+' · '+t.zone+' · '+t.place;fleetPaths.forEach(function(p,i){p.style.opacity=i===selectedTruck?'1':'.15';p.style.strokeWidth=i===selectedTruck?'5':'2'})};document.getElementById('pauseTruckFeed').onclick=function(){document.getElementById('liveToggle').click();this.textContent=running?'Pause movement':'Resume movement'};document.getElementById('drawerBack').classList.add('show')}
document.getElementById('inspectVehicle').onclick=showVehicle;
// The queue always opens a service case, even after viewing a vehicle.
document.getElementById('openQueue').onclick=function(){var first=stops.find(function(s){return s.dataset.kind==='alert'});selectStop(first);openDrawer(first)};
document.getElementById('fitMap').onclick=function(){zoomLevel=1;applyZoom();fleetPaths.forEach(function(p){p.style.opacity='';p.style.strokeWidth=''});document.getElementById('mapHeading').textContent='Ikeja Central · Zone IKJ-04'};
selectTruck(0);requestAnimationFrame(drawFleet);
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)document.getElementById('liveToggle').click();
'''
s=s.replace('</body>','<script>'+script+'</script></body>')
p.write_text(s)
print('Updated LAWMA identity, three vector trucks, vehicle detail panel, and map controls.')
